// Shared setup for the plan walkthrough specs (chat-plans, plan-validation):
// the canned deltas the server's stub OpenSpec CLI serves, and a git
// repository whose OpenSpec root registers the changes the walkthroughs'
// plans name — so a validation resolves them as registered and can reach a
// Ready report through the UI's own Validate button. The stub itself is
// generated by playwright.config.ts into the e2e stub-bin; nothing here
// spawns the real CLI from the test worker.
import { expect, type Locator, type Page } from '@playwright/test'
import { execFileSync } from 'node:child_process'
import { mkdirSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'

/** The GitHub-shaped remote the walkthrough origins hide behind. */
export const GITHUB_URL = 'https://github.com/acme/walkthrough.git'

export function git(args: string[], cwd?: string): string {
  return execFileSync('git', args, { cwd, encoding: 'utf8' })
}

export async function createChat(page: Page, root: string, name: string, group: string) {
  await page.getByRole('button', { name: 'New session', exact: true }).first().click()
  const dialog = page.getByRole('dialog', { name: 'New Session' })
  await dialog.getByLabel('Project Path').fill(root)
  await dialog.getByLabel('Group').selectOption(group)
  await dialog.getByLabel('Display Name').fill(name)
  await dialog.getByRole('button', { name: 'Create', exact: true }).click()
  await expect(page.getByTestId('chat-view')).toContainText(name)
  return (await page.locator('[data-session-id^="chat-"]').filter({ hasText: name }).first().getAttribute('data-session-id'))!
}

/** A bare origin behind a GitHub-shaped remote, so the fixture probe reads a
 * base. The remote URL defaults to GITHUB_URL; pass another so a second
 * walkthrough team's fixture PRs live in their own repository. */
export function initOrigin(root: string, origin: string, githubUrl: string = GITHUB_URL): void {
  git(['init', '-q', '--bare', '-b', 'master', origin])
  git(['add', '-A'], root)
  git(['-c', 'user.email=t@e', '-c', 'user.name=T', 'commit', '-q', '-m', 'base'], root)
  git(['remote', 'add', 'origin', origin], root)
  git(['push', '-q', 'origin', 'master'], root)
  git(['remote', 'set-url', 'origin', githubUrl], root)
  git(['config', `url.${origin}.insteadOf`, githubUrl], root)
}

/** One canned delta touch the stub serves for a change. */
export interface StubTouch {
  capability: string
  operation: string
  requirement: string
}

/**
 * The canned deltas the stub CLI serves, one file per change: the spec
 * rewrites them between steps (or sets them once up front).
 */
export function serveDeltas(deltas: Record<string, readonly StubTouch[]>): void {
  const dir = join(process.env.E2E_TMUX_TMPDIR!, 'openspec-deltas')
  mkdirSync(dir, { recursive: true })
  for (const [change, touches] of Object.entries(deltas)) {
    writeFileSync(
      join(dir, `${change}.json`),
      JSON.stringify(touches.map(touch => ({
        spec: touch.capability, operation: touch.operation,
        requirement: { name: touch.requirement }, description: `${change} ${touch.requirement}`,
      }))),
    )
  }
}

/**
 * A git repository whose OpenSpec root registers each named change (a
 * proposal and a chat spec file), plus the team's group files, so a plan
 * naming the changes validates as registered. Returns nothing; callers pass
 * the root as the chat's project path. `extraFiles` optionally writes more
 * repository files (repo-relative paths), e.g. a long proposal a workspace
 * reader can scroll; the walkthroughs that need none are unaffected.
 */
export function initPlanRepository(root: string, changes: readonly string[], groups: Record<string, string>,
  extraFiles: Readonly<Record<string, string>> = {}): void {
  execFileSync('git', ['init', '-q', root])
  for (const change of changes) {
    mkdirSync(join(root, 'openspec', 'changes', change, 'specs', 'chat'), { recursive: true })
    writeFileSync(join(root, 'openspec', 'changes', change, 'proposal.md'), `# ${change}\n`)
    writeFileSync(join(root, 'openspec', 'changes', change, 'specs', 'chat', 'spec.md'), '## ADDED Requirements\n### Requirement: Presence\n')
  }
  for (const [path, content] of Object.entries(extraFiles)) {
    mkdirSync(dirname(join(root, path)), { recursive: true })
    writeFileSync(join(root, path), content)
  }
  mkdirSync(join(root, '.kawai', 'groups'), { recursive: true })
  for (const [id, body] of Object.entries(groups)) {
    writeFileSync(join(root, '.kawai', 'groups', `${id}.md`), body)
  }
}

/** Validate one revision through the UI and wait for its standing to read Ready. */
export async function validateUntilReady(panel: { getByTestId: (id: string) => Locator }, revision: number): Promise<void> {
  await panel.getByTestId(`plan-validate-${revision}`).click()
  await expect(panel.getByTestId(`plan-validation-${revision}-standing`)).toContainText('Ready', { timeout: 20_000 })
}


/** Plan seed options a walkthrough can specialize; the defaults keep plan-execution's shape. */
export interface SeedPlanOptions {
  title?: string
  goal?: string
  /** Names the plan's Lead role; the group must be in `roles`. */
  leadGroup?: string
  roles?: Array<{ group: string; profiles: string[] }>
}

/** Seed an approved plan (and only the plan) through the stores, as the human. Returns its id. */
export function seedPlan(root: string, options: SeedPlanOptions = {}): string {
  const dbPath = process.env.AGENTBOARD_DB_PATH!
  if (!dbPath.startsWith(process.env.E2E_TMUX_TMPDIR!)) throw new Error('Refuse seeding a non-isolated database')
  const roles = options.roles ?? [{ group: 'devs', profiles: [] }, { group: 'reviewers', profiles: [] }]
  const script = `
    import { initDatabase } from './src/server/db';
    import { PlanStore } from './src/server/plans/planStore';
    import { resolveTeam } from './src/server/team/teamIdentity';
    import { normalizePlanContent } from './src/shared/plans';
    import { retryOnSqliteBusy } from './src/server/__tests__/sqliteBusyRetry';
    const sessions = initDatabase({ path: ${JSON.stringify(dbPath)} });
    sessions.db.exec('PRAGMA busy_timeout = 5000');
    const plans = new PlanStore(sessions.db);
    const teamId = (await resolveTeam(${JSON.stringify(root)})).teamId;
    // The server is a second writer on this database: a BUSY on the deferred
    // read→write upgrade bypasses busy_timeout, so the whole seed runs as one
    // transaction and re-runs on BUSY (a throw rolls everything back).
    await retryOnSqliteBusy(() => plans.atomically(() => {
      const planId = plans.insertPlan({ teamId, title: ${JSON.stringify(options.title ?? 'Execution walkthrough')}, creator: { kind: 'human', sessionId: null } });
      const content = normalizePlanContent({
        goal: ${JSON.stringify(options.goal ?? 'Ship the walkthrough')}, successCriteria: ['The change lands through the execution'],
        changes: [{ change: 'walk-api', dependsOn: [], group: 'devs', acceptance: [], extraChecks: [], guidance: '' }],
        roles: ${JSON.stringify(roles)}, reviewGroup: 'reviewers',${options.leadGroup ? `\n        leadGroup: ${JSON.stringify(options.leadGroup)},` : ''}
      });
      const revision = plans.insertRevision(planId, { content, contentHash: 'seed-hash-' + planId, pin: null, author: { kind: 'human', sessionId: null } });
      plans.setRevisionStatus(planId, revision, 'approved');
      plans.setCurrentApproved(planId, revision);
      console.log('PLAN:' + planId);
    }));
    sessions.close();
  `
  const stdout = execFileSync('bun', ['-e', script], { cwd: process.cwd(), encoding: 'utf8' })
  const line = stdout.split('\n').find(entry => entry.startsWith('PLAN:'))
  if (!line) throw new Error(`seedPlan printed no plan id: ${stdout}`)
  return line.slice('PLAN:'.length)
}

/** Round options a walkthrough can specialize; the defaults keep plan-execution's shape. */
export interface SubmitRoundOptions {
  /** The review verdict the findings carry (default pass). */
  verdict?: 'pass' | 'fail'
}

/**
 * The implementer's result, then the reviewer's findings — the agent tool
 * path over the same database. Returns the tool's printed outcome line.
 */
export function submitRound(root: string, mode: 'result' | 'findings', implementer: string, reviewer: string, options: SubmitRoundOptions = {}): string {
  const dbPath = process.env.AGENTBOARD_DB_PATH!
  if (!dbPath.startsWith(process.env.E2E_TMUX_TMPDIR!)) throw new Error('Refuse seeding a non-isolated database')
  const script = `
    import { join } from 'node:path';
    import { initDatabase } from './src/server/db';
    import { resolveTeam } from './src/server/team/teamIdentity';
    import { MailboxStore } from './src/server/team/mailboxStore';
    import { AssignmentStore } from './src/server/team/assignmentStore';
    import { TaskStore } from './src/server/team/taskStore';
    import { TaskService } from './src/server/team/TaskService';
    import { TaskResultService } from './src/server/team/TaskResultService';
    import { taskHandlers } from './src/server/team/taskTools';
    import { composeExecutionCore } from './src/server/plans/planComposition';
    import { retryOnSqliteBusy } from './src/server/__tests__/sqliteBusyRetry';
    try {
      const [file, root, mode, implementer, reviewer, verdict] = JSON.parse(await Bun.stdin.text());
      const sessions = initDatabase({ path: file });
      sessions.db.exec('PRAGMA busy_timeout = 5000');
      const db = sessions.db;
      const core = composeExecutionCore(db);
      const mail = new MailboxStore(db);
      const taskStore = new TaskStore(db, mail, new AssignmentStore(db, mail));
      const tasks = new TaskService(taskStore, {
        getSession: id => sessions.getChatSession(id), homeDir: process.env.HOME,
        restoreSession: () => undefined, ownership: core.ownership,
      });
      const results = new TaskResultService(tasks, {
        getSession: id => sessions.getChatSession(id), ownership: core.ownership, records: () => [],
      });
      // CI's one-server fixture run shares one database across walkthrough
      // teams, and two name their change walk-api: scope to this spec's own
      // team — each spec runs one execution in its own repo, so the newest
      // row with a task id inside the team is this spec's own execution's.
      const teamId = (await resolveTeam(root)).teamId;
      const row = db.prepare("SELECT task_id FROM plan_execution_changes WHERE team_id = ? AND change = 'walk-api' AND task_id IS NOT NULL ORDER BY rowid DESC").get(teamId);
      if (!row) throw new Error('no owned task for walk-api yet');
      const taskId = row.task_id;
      if (mode === 'result') {
        const commit = Bun.spawnSync(['git', 'rev-parse', 'HEAD'], { cwd: join(root, '.worktrees', 'walk-api') }).stdout.toString().trim();
        const asImplementer = taskHandlers(tasks, implementer, results);
        await retryOnSqliteBusy(() => asImplementer.task_submit_result({ task_id: taskId, summary: 'Implemented walk-api', commit, tests: [{ description: 'unit', outcome: 'pass' }] }));
        console.log('RESULT:' + commit);
      } else {
        // The verdict counts only the review handoff's claimant's findings:
        // wait for the dispatched review to be claimed, then answer as that
        // reviewer (the tool path, exactly as the agent would).
        let claimant = null;
        for (let attempt = 0; attempt < 30 && claimant === null; attempt++) {
          const row = db.prepare("SELECT claimed_by FROM team_task_assignments WHERE task_id = ? AND handoff_kind = 'review' AND superseded_by IS NULL AND claimed_by IS NOT NULL ORDER BY rowid DESC").get(taskId);
          claimant = row?.claimed_by ?? null;
          if (claimant === null) await new Promise(resolve => setTimeout(resolve, 1000));
        }
        if (claimant === null) {
          // Self-diagnosing: a CI timeout names its cause. A stopped change
          // dispatches no review; a dispatched one names its mail state.
          const change = db.prepare("SELECT state, step, stop_reason, stop_detail_json FROM plan_execution_changes WHERE change = 'walk-api' AND task_id = ? ORDER BY rowid DESC").get(taskId) ?? {};
          const handoff = db.prepare("SELECT m.state AS mail_state, m.reason AS mail_reason FROM team_task_assignments a LEFT JOIN team_messages m ON m.id = a.message_id WHERE a.task_id = ? AND a.handoff_kind = 'review' AND a.superseded_by IS NULL ORDER BY a.rowid DESC").get(taskId) ?? null;
          const stage = change.state === 'stopped'
            ? 'the change stopped (' + (change.stop_reason ?? 'unknown') + (change.stop_detail_json ? ' — ' + change.stop_detail_json : '') + ')'
            : 'the change is ' + (change.state ?? 'unknown') + (change.step ? ' at step ' + change.step : '');
          const dispatch = handoff
            ? 'the review was dispatched, its mail ' + (handoff.mail_state ?? 'unknown') + (handoff.mail_reason ? ' (' + handoff.mail_reason + ')' : '')
            : 'the review was never dispatched';
          throw new Error('the review handoff was never claimed in 30s: ' + stage + '; ' + dispatch);
        }
        const result = db.prepare('SELECT id FROM team_task_results WHERE task_id = ? ORDER BY rowid DESC').get(taskId);
        if (!result) throw new Error('no result yet');
        const asReviewer = taskHandlers(tasks, claimant, results);
        const findings = verdict === 'fail'
          ? 'Fail: the review found the walkthrough change incomplete.'
          : 'Clean: the walkthrough change is sound.';
        // Not retried: submitFindings makes three autocommits (the findings
        // INSERT, then the journal note's INSERT and UPDATE), so a BUSY after
        // the first would duplicate them on a re-run; its statements start
        // from TRANS_NONE and take the busy handler.
        await asReviewer.task_submit_findings({ task_id: taskId, result_id: result.id, kind: 'review', verdict, findings });
        console.log('FINDINGS:ok:' + claimant);
      }
      sessions.close();
    } catch (error) {
      console.error('ROUND-FAILED:', error instanceof Error ? error.stack : String(error));
      process.exit(1);
    }
  `
  return execFileSync('bun', ['-e', script], {
    cwd: process.cwd(), input: JSON.stringify([dbPath, root, mode, implementer, reviewer, options.verdict ?? 'pass']), encoding: 'utf8',
  }).trim()
}
